import asyncio
seen = {}
async def fetch(url):
    seen[url] = seen.get(url, 0) + 1
    if url == 'fragile' and seen[url] == 1:
        raise RuntimeError('temporary')
    if url == 'broken':
        raise RuntimeError('permanent')
    return []
result = asyncio.run(crawl_work_queue(['fragile', 'broken'], fetch, workers=1, retries=1))
assert result == {
    'scheduled': ['fragile', 'broken'],
    'completed': ['fragile'],
    'failed': ['broken'],
    'attempts': {'fragile': 2, 'broken': 2},
}
